from datetime import date
from decimal import Decimal, InvalidOperation


class Loyalty:
    def __init__(self) -> None:
        self._transactions: dict[str, list[tuple[date, int]]] = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        try:
            value = Decimal(str(amount))
            if not value.is_finite() or value <= 0:
                raise ValueError("Purchase amount must be positive and finite")
            earned = int(value // 10)
        except (InvalidOperation, OverflowError) as exc:
            raise ValueError("Invalid purchase amount") from exc

        self._transactions.setdefault(customer, []).append((day, earned))
        return earned

    def balance(self, customer: str, day: date) -> int:
        return sum(
            points
            for transaction_day, points in self._transactions.get(customer, [])
            if transaction_day <= day
        )

    def redeem(self, customer: str, points: int, day: date) -> None:
        if not isinstance(points, int) or points < 0 or points % 100 != 0:
            raise ValueError("Points must be a nonnegative multiple of 100")
        if points > self.balance(customer, day):
            raise ValueError("Insufficient points")
        self._transactions.setdefault(customer, []).append((day, -points))
